def get_func_in_mro(obj: Any, code: CodeType) ->Optional[Callable[..., Any]]:
    if obj is None:
        return None

    # Check if obj itself has the code
    func = _has_code(obj, code)
    if func is not None:
        return func

    # Walk through the MRO to find the function
    if hasattr(obj, '__class__'):
        for cls in inspect.getmro(obj.__class__):
            if hasattr(cls, code.co_name):
                attr = getattr(cls, code.co_name)
                func = _has_code(attr, code)
                if func is not None:
                    return func

    # Also check the class itself if obj is a class
    if isinstance(obj, type):
        for cls in inspect.getmro(obj):
            if hasattr(cls, code.co_name):
                attr = getattr(cls, code.co_name)
                func = _has_code(attr, code)
                if func is not None:
                    return func

    # Handle special case for properties and descriptors
    if hasattr(obj, '__class__') and hasattr(obj.__class__, code.co_name):
        attr = getattr(obj.__class__, code.co_name)
        if isinstance(attr, property):
